import json
with open('/app/resources/treasury_bulletin_1990_06.json', 'r') as f:
    data = json.load(f)

# Look for ESF related content in the entire document
def search_for_esf(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if 'ESF' in str(k).upper() or 'exchange' in str(k).lower() or 'stabilization' in str(k).lower() or 'poland' in str(k).lower() or 'germany' in str(k).lower() or 'zloty' in str(k).lower() or 'mark' in str(k).lower():
                print(f'{new_path}: {str(v)[:100]}')
            search_for_esf(v, new_path)
    elif isinstance(obj, list) and len(obj) < 100:
        for i, item in enumerate(obj[:5]):
            search_for_esf(item, f'{path}[{i}]')

search_for_esf(data)
