import json

with open('/app/resources/treasury_bulletin_1990_06.json', 'r') as f:
    data = json.load(f)

# Let me find the pages with ESF data
def find_esf_data(obj, path='', depth=0):
    if depth > 4:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'esf' in str(k).lower() or 'exchange' in str(k).lower() and depth < 3:
                print(f"{path}.{k}: {str(v)[:150]}")
            find_esf_data(v, f'{path}.{k}', depth+1)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:10]):
            find_esf_data(item, f'{path}[{i}]', depth+1)

find_esf_data(data)
